_weather.each do |row|
  loc = Location.find_by!(name: row[:location_name])
  WeatherReading.find_or_create_by!(location: loc, date: row[:date]) do |wr|
    wr.assign_attributes(row.except(:location_name, :date))
  end
end

puts "Done! #{Location.count} locations, #{GrowthStage.count} growth stages, #{Field.count} fields, #{PlantingEvent.count} planting events, #{WeatherReading.count} weather readings."
